package com.ecommerce.auth; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.security.Key; import java.util.*;
@Service public class JwtService { private final Key key; private final long exp; private final long refreshExp; public JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.expiration-ms}")long exp,@Value("${app.jwt.refresh-expiration-ms}")long refreshExp){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.exp=exp;this.refreshExp=refreshExp;} public String token(String email,String role){return build(email,role,exp);} public String refresh(String email,String role){return build(email,role,refreshExp);} private String build(String email,String role,long ttl){Date now=new Date();return Jwts.builder().subject(email).claim("role",role).issuedAt(now).expiration(new Date(now.getTime()+ttl)).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith((javax.crypto.SecretKey)key).build().parseSignedClaims(token).getPayload().getSubject();} public boolean valid(String token){try{subject(token);return true;}catch(JwtException|IllegalArgumentException e){return false;}} }
